const pts = (s) => s.trim().split(" ").map((p) => p.split(",").map((v) => Number(v) / 2));
/* each facet grown by a pixel round its middle, so neighbours overlap and no seam shows between them */
const grow = (l, by) => { const cx = l.reduce((a, p) => a + p[0], 0) / l.length, cy = l.reduce((a, p) => a + p[1], 0) / l.length;
  return l.map(([x, y]) => { const d = Math.hypot(x - cx, y - cy) || 1; return [x + (x - cx) / d * by, y + (y - cy) / d * by]; }); };
const LAYERS = [[[pts(SIL)], hex("#8EBFEB")]].concat(FACETS.map((f) => { const i = f.indexOf(" "); return [[grow(pts(f.slice(i + 1)), 0.9)], hex(COLS[Number(f.slice(0, i))])]; }));
const TOP = hex("#FFFFFF"), BOTTOM = hex("#E6EFFA");

/* nonzero fill of the loops, 4 × 4 samples a pixel, after mapping the 512 grid onto the icon */
const SS = 4;
function coverage(loops, size, map) {
  const cov = new Float32Array(size * size);
  const edges = [];
  for (const l of loops) for (let i = 0; i < l.length; i++) {
    const a = map(l[i]), b = map(l[(i + 1) % l.length]);
    if (a[1] !== b[1]) edges.push(a[1] < b[1] ? [a[0], a[1], b[0], b[1], 1] : [b[0], b[1], a[0], a[1], -1]);
  }
  const w = 1 / (SS * SS);
  for (let sy = 0; sy < size * SS; sy++) {
    const y = (sy + 0.5) / SS, row = Math.floor(sy / SS) * size;
    const xs = [];
    for (const [x1, y1, x2, y2, d] of edges) if (y >= y1 && y < y2) xs.push([x1 + (y - y1) / (y2 - y1) * (x2 - x1), d]);
    if (!xs.length) continue;
    xs.sort((p, q) => p[0] - q[0]);
    let wind = 0;
    for (let k = 0; k < xs.length - 1; k++) {
      wind += xs[k][1];
      if (!wind) continue;
      /* the sample columns sx with (sx + 0.5) / SS in [x0, x1) */
      const s0 = Math.max(0, Math.ceil(xs[k][0] * SS - 0.5)), s1 = Math.min(size * SS, Math.ceil(xs[k + 1][0] * SS - 0.5));
      for (let sx = s0; sx < s1; sx++) cov[row + Math.floor(sx / SS)] += w;
    }
  }
  return cov;
}

function icon(size, { scale = 1 } = {}) {
  const buf = Buffer.alloc(size * size * 4);
  const k = size / 512 * scale, off = size / 2 - 256 * k;
  const map = ([x, y]) => [off + x * k, off + y * k];
  const px = new Float32Array(size * size * 3);
  for (let y = 0; y < size; y++) {
    const t = (y + 0.5) / size;
    for (let x = 0; x < size; x++) for (let c = 0; c < 3; c++) px[(y * size + x) * 3 + c] = TOP[c] + (BOTTOM[c] - TOP[c]) * t;
  }
  for (const [loops, col] of LAYERS) {
    const cov = coverage(loops, size, map);
    for (let i = 0; i < size * size; i++) {
      const a = Math.min(1, cov[i]);
      if (a > 0) for (let c = 0; c < 3; c++) px[i * 3 + c] += (col[c] - px[i * 3 + c]) * a;
    }
  }
  for (let i = 0; i < size * size; i++) {
    buf[i * 4] = Math.round(px[i * 3]); buf[i * 4 + 1] = Math.round(px[i * 3 + 1]); buf[i * 4 + 2] = Math.round(px[i * 3 + 2]); buf[i * 4 + 3] = 255;
  }
  return png(size, size, buf);
}

const out = path.join(process.cwd(), "public", "icons");
fs.mkdirSync(out, { recursive: true });
const files = [
  ["icon-192.png", icon(192)],
  ["icon-512.png", icon(512)],
  ["icon-maskable-512.png", icon(512, { scale: 0.8 })],
  ["apple-touch-icon.png", icon(180)],
  ["favicon-32.png", icon(32)],
];
for (const [name, data] of files) {
  fs.writeFileSync(path.join(out, name), data);
  console.log("wrote public/icons/" + name + " (" + data.length + " bytes)");
}
